cat > 'app/src/main/java/com/meraassistant/AssistantService.kt' <<'EOF_MERA'
package com.meraassistant

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.content.Intent
import android.graphics.Path
import android.graphics.Rect
import android.media.AudioManager
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo

/**
 * Chinu's "hands": system actions that a normal app can't do.
 * Screenshot, lock, home, back, recents, notifications, power menu, split screen,
 * scrolling, and pressing WhatsApp's Send button automatically.
 */
class AssistantService : AccessibilityService() {

    private val handler = Handler(Looper.getMainLooper())
    private var sendUntil = 0L
    private var onSent: (() -> Unit)? = null
    private var overlay: ChinuOverlay? = null

    /** ✨ Siri-style Chinu on top of any screen */
    /** 💞 Full-screen floating hearts + a little glass card (when the partner sends love) */
    fun showLove(emoji: String, text: String) {
        try {
            val wm = getSystemService(android.view.WindowManager::class.java)
            val root = android.widget.FrameLayout(this)
            val fx = LoveFx(this)
            root.addView(fx, android.widget.FrameLayout.LayoutParams(-1, -1))
            val card = android.widget.TextView(this).apply {
                this.text = "$emoji  $text"
                textSize = 17f
                setTextColor(0xFF3B1F4A.toInt())
                gravity = android.view.Gravity.CENTER
                background = Ui.glass(this@AssistantService, 26f, 0xDD)
                val pd = Ui.dp(this@AssistantService, 18f)
                setPadding(pd, pd, pd, pd)
                elevation = Ui.dp(this@AssistantService, 10f).toFloat()
            }
            root.addView(card, android.widget.FrameLayout.LayoutParams(-1, -2, android.view.Gravity.CENTER).apply {
                val m = Ui.dp(this@AssistantService, 28f)
                setMargins(m, 0, m, 0)
            })
            val lp = android.view.WindowManager.LayoutParams(
                -1, -1,
                android.view.WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,
                android.view.WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                    android.view.WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE or
                    android.view.WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
                android.graphics.PixelFormat.TRANSLUCENT
            )
            wm.addView(root, lp)
            card.scaleX = 0.6f
            card.scaleY = 0.6f
            card.alpha = 0f
            card.animate().scaleX(1f).scaleY(1f).alpha(1f).setDuration(350).start()
            fx.post { fx.burst(emoji, 34) }
            handler.postDelayed({
                card.animate().alpha(0f).setDuration(300).start()
            }, 4200)
            handler.postDelayed({
                try {
                    wm.removeView(root)
                } catch (e: Exception) {
                }
            }, 5200)
        } catch (e: Exception) {
        }
    }

    fun showOverlay(command: String) {
        try {
            val o = overlay ?: ChinuOverlay(this).also { overlay = it }
            o.show(command)
        } catch (e: Exception) {
            // overlay fail ho to bhi service crash na ho (warna Android Accessibility band kar deta hai)
        }
    }

    override fun onServiceConnected() {
        super.onServiceConnected()
        Speaker.load(this)
        instance = this
        getSharedPreferences("settings", MODE_PRIVATE).edit().putBoolean("accWasOn", true).apply()
        BeepMuter.forceUnmute(this)
        try {
            if (overlay == null) overlay = ChinuOverlay(this)
        } catch (e: Exception) {
        }
    }

    override fun onUnbind(intent: Intent?): Boolean {
        overlay?.dismiss(true)
        instance = null
        return super.onUnbind(intent)
    }

    override fun onDestroy() {
        instance = null
        super.onDestroy()
    }

    override fun onInterrupt() {}

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        try {
            handleEvent(event)
        } catch (e: Exception) {
        }
    }

    private fun handleEvent(event: AccessibilityEvent?) {
        if (System.currentTimeMillis() > sendUntil) return
        val pkg = event?.packageName?.toString() ?: return
        if (pkg == "com.whatsapp" || pkg == "com.whatsapp.w4b") trySend()
    }

    // ---------------- WhatsApp auto-send ----------------
    /** Next 15 seconds: jaise hi WhatsApp chat khule, Send button daba do */
    fun armWhatsAppSend(sent: (() -> Unit)? = null) {
        sendUntil = System.currentTimeMillis() + 15_000
        onSent = sent
        // events na aaye to bhi kuch baar khud try karo
        for (d in listOf(1500L, 2500L, 3500L, 5000L)) handler.postDelayed({ trySend() }, d)
    }

    private fun trySend() {
        if (System.currentTimeMillis() > sendUntil) return
        val root = rootInActiveWindow ?: return
        val pkg = root.packageName?.toString() ?: return
        if (pkg != "com.whatsapp" && pkg != "com.whatsapp.w4b") return
        val byId = root.findAccessibilityNodeInfosByViewId("$pkg:id/send")
        val target = byId.firstOrNull { it.isVisibleToUser && it.isEnabled } ?: findByDescription(root)
        if (target != null && clickNode(target)) {
            sendUntil = 0
            onSent?.invoke()
            onSent = null
        }
    }

    private fun findByDescription(node: AccessibilityNodeInfo?, depth: Int = 0): AccessibilityNodeInfo? {
        if (node == null || depth > 30) return null
        val d = node.contentDescription?.toString()?.lowercase() ?: ""
        if ((d == "send" || d == "भेजें") && node.isVisibleToUser) return node
        for (i in 0 until node.childCount) {
            val r = findByDescription(node.getChild(i), depth + 1)
            if (r != null) return r
        }
        return null
    }

    private fun clickNode(n: AccessibilityNodeInfo): Boolean {
        var cur: AccessibilityNodeInfo? = n
        var hops = 0
        while (cur != null && hops < 4) {
            if (cur.isClickable) return cur.performAction(AccessibilityNodeInfo.ACTION_CLICK)
            cur = cur.parent
            hops++
        }
        return n.performAction(AccessibilityNodeInfo.ACTION_CLICK)
    }

    // ---------------- 🎵 Auto play (no tapping needed) ----------------
    private fun retry(times: Int, every: Long, first: Long, block: () -> Boolean) {
        var left = times
        val r = object : Runnable {
            override fun run() {
                val done = try {
                    block()
                } catch (e: Exception) {
                    false
                }
                left--
                if (!done && left > 0) handler.postDelayed(this, every)
            }
        }
        handler.postDelayed(r, first)
    }

    /** A real song/video is playing (Chinu's own voice does not count) */
    private fun musicPlaying(): Boolean {
        val am = getSystemService(AUDIO_SERVICE) as AudioManager
        try {
            val media = am.activePlaybackConfigurations.any { c ->
                val u = c.audioAttributes.usage
                u == android.media.AudioAttributes.USAGE_MEDIA || u == android.media.AudioAttributes.USAGE_GAME ||
                    u == android.media.AudioAttributes.USAGE_UNKNOWN
            }
            return media && !MainActivity.speaking
        } catch (e: Exception) {
        }
        return am.isMusicActive && !MainActivity.speaking
    }

    /** Pause whatever is playing right now (so a new song can be detected) */
    fun mediaPauseKey() {
        try {
            val am = getSystemService(AUDIO_SERVICE) as AudioManager
            am.dispatchMediaKeyEvent(android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN, android.view.KeyEvent.KEYCODE_MEDIA_PAUSE))
            am.dispatchMediaKeyEvent(android.view.KeyEvent(android.view.KeyEvent.ACTION_UP, android.view.KeyEvent.KEYCODE_MEDIA_PAUSE))
        } catch (e: Exception) {
        }
    }

    /** Press the hardware-style PLAY key (works for most music apps) */
    private fun mediaPlayKey() {
        try {
            val am = getSystemService(AUDIO_SERVICE) as AudioManager
            am.dispatchMediaKeyEvent(android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN, android.view.KeyEvent.KEYCODE_MEDIA_PLAY))
            am.dispatchMediaKeyEvent(android.view.KeyEvent(android.view.KeyEvent.ACTION_UP, android.view.KeyEvent.KEYCODE_MEDIA_PLAY))
        } catch (e: Exception) {
        }
    }

    /** Text of a node plus everything inside it (a whole result row) */
    private fun rowText(n: AccessibilityNodeInfo): String {
        val sb = StringBuilder(label(n))
        for (c in allNodes(n).take(40)) sb.append(' ').append(label(c))
        return sb.toString().lowercase()
    }

    /** Score a search-result row: more song-title words = better, "Song" rows best, videos/artists/playlists worse */
    private fun songScore(row: String, words: List<String>): Int {
        var s = words.count { row.contains(it) } * 10
        if (s == 0) return 0
        if (Regex("\\b(song|गाना|गीत)\\b").containsMatchIn(row)) s += 15
        if (row.contains("top result") || row.contains("सबसे")) s += 5
        if (Regex("\\b(video|वीडियो)\\b").containsMatchIn(row)) s -= 6
        if (Regex("\\b(artist|album|playlist|profile|subscribers|episode|podcast)\\b").containsMatchIn(row)) s -= 12
        return s
    }

    private fun label(n: AccessibilityNodeInfo): String =
        ((n.text?.toString() ?: "") + " " + (n.contentDescription?.toString() ?: "")).lowercase().trim()

    private fun findNode(root: AccessibilityNodeInfo?, pred: (AccessibilityNodeInfo) -> Boolean): AccessibilityNodeInfo? {
        if (root == null) return null
        val stack = ArrayDeque<AccessibilityNodeInfo>()
        stack.addLast(root)
        var seen = 0
        while (stack.isNotEmpty() && seen < 2500) {
            val n = stack.removeFirst()
            seen++
            if (n.isVisibleToUser && pred(n)) return n
            for (i in 0 until n.childCount) n.getChild(i)?.let { stack.addLast(it) }
        }
        return null
    }

    private fun allNodes(root: AccessibilityNodeInfo?): List<AccessibilityNodeInfo> {
        val out = mutableListOf<AccessibilityNodeInfo>()
        if (root == null) return out
        val stack = ArrayDeque<AccessibilityNodeInfo>()
        stack.addLast(root)
        while (stack.isNotEmpty() && out.size < 2500) {
            val n = stack.removeFirst()
            out.add(n)
            for (i in 0 until n.childCount) n.getChild(i)?.let { stack.addLast(it) }
        }
        return out
    }

    private fun height(n: AccessibilityNodeInfo): Int {
        val r = Rect()
        n.getBoundsInScreen(r)
        return r.height()
    }

    private fun top(n: AccessibilityNodeInfo): Int {
        val r = Rect()
        n.getBoundsInScreen(r)
        return r.top
    }

    private fun typeAndSearch(edit: AccessibilityNodeInfo, query: String) {
        edit.performAction(AccessibilityNodeInfo.ACTION_FOCUS)
        edit.performAction(AccessibilityNodeInfo.ACTION_CLICK)
        val args = Bundle()
        args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, query)
        edit.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args)
        if (Build.VERSION.SDK_INT >= 30) {
            edit.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_IME_ENTER.id)
        }
    }

    /** YouTube (or any YouTube-like app): tap the first video in the search results */
    fun autoPlayYouTube(query: String, pkg: String = "com.google.android.youtube") {
        val screenH = resources.displayMetrics.heightPixels
        retry(times = 10, every = 1200, first = 3000) {
            val root = rootInActiveWindow ?: return@retry false
            if (root.packageName?.toString() != pkg) return@retry false
            val video = allNodes(root)
                .filter { n ->
                    val l = label(n)
                    n.isVisibleToUser && top(n) > screenH * 0.12 &&
                        (l.contains("minute") || l.contains("second") || l.contains("views") || l.contains("मिनट") || l.contains("व्यू"))
                }
                .minByOrNull { top(it) } ?: return@retry false
            clickNode(video)
        }
    }

    /**
     * Any app: wait a bit (some apps start playing by themselves); if nothing is playing,
     * type the song in the app's search box, open the first result and press Play.
     */
    fun autoPlayInApp(pkg: String, query: String, waitForMusic: Boolean, resultsLink: Intent? = null) {
        val words = query.lowercase().split(Regex("\\s+")).filter { it.length >= 3 }
        val screenH = resources.displayMetrics.heightPixels
        var step = 0
        var searchBottom = 0
        handler.postDelayed({
            if (waitForMusic && musicPlaying()) return@postDelayed
            var firstDelay = 0L
            if (resultsLink != null) {
                // App ka search results page seedha kholo, phir pehla gaana tap karo
                try {
                    startActivity(resultsLink.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
                    step = 3
                    firstDelay = 2800L
                } catch (e: Exception) {
                }
            }
            retry(times = 16, every = 1100, first = firstDelay) {
                val root = rootInActiveWindow ?: return@retry false
                if (root.packageName?.toString() != pkg) return@retry false
                when (step) {
                    0 -> {
                        val edit = findNode(root) { it.isEditable }
                        if (edit != null) {
                            typeAndSearch(edit, query)
                            searchBottom = top(edit) + 60
                            step = 2
                        } else {
                            val s = findNode(root) { n ->
                                val l = label(n)
                                (n.isClickable || n.parent?.isClickable == true) && (l.contains("search") || l.contains("खोज"))
                            }
                            if (s != null) {
                                clickNode(s)
                                step = 1
                            }
                        }
                        false
                    }
                    1 -> {
                        val edit = findNode(root) { it.isEditable }
                        if (edit != null) {
                            typeAndSearch(edit, query)
                            searchBottom = top(edit) + 60
                            step = 2
                        }
                        false
                    }
                    2 -> {
                        step = 3            // results load ho rahe hain
                        false
                    }
                    3 -> {
                        if (musicPlaying()) return@retry true
                        val minTop = maxOf(searchBottom, (screenH * 0.12).toInt())
                        // whole clickable rows below the search bar, best "song" match first
                        val rows = allNodes(root)
                            .filter { n -> n.isVisibleToUser && n.isClickable && !n.isEditable && !n.isScrollable && top(n) > minTop && height(n) < screenH * 0.3 }
                            .map { n -> n to songScore(rowText(n), words) }
                            .filter { it.second > 0 }
                        val best = rows.maxWithOrNull(compareBy<Pair<AccessibilityNodeInfo, Int>> { it.second }.thenBy { -top(it.first) })
                        val target = best?.first ?: allNodes(root)
                            .filter { n -> n.isVisibleToUser && !n.isEditable && top(n) > minTop && words.any { label(n).contains(it) } }
                            .minByOrNull { top(it) }
                        if (target != null) {
                            clickNode(target)
                            step = 4
                        }
                        false
                    }
                    4 -> {
                        if (musicPlaying()) return@retry true
                        val play = findNode(root) { n ->
                            val l = label(n)
                            l == "play" || l.startsWith("play ") || l.contains("play all") || l.contains("shuffle") ||
                                l == "चलाएं" || l.contains("प्ले") || l == "resume"
                        }
                        if (play != null) clickNode(play)
                        step = 5
                        false
                    }
                    else -> {
                        if (!musicPlaying()) mediaPlayKey()
                        true
                    }
                }
            }
        }, if (waitForMusic) 3500L else 2500L)
    }

    // ---------------- ⚙️ Turn any setting ON / OFF (like a person would) ----------------
    /** Looks at every window on screen (the quick-settings shade is a separate window) */
    private fun allRoots(): List<AccessibilityNodeInfo> {
        val out = mutableListOf<AccessibilityNodeInfo>()
        try {
            for (w in windows) w.root?.let { out.add(it) }
        } catch (e: Exception) {
        }
        rootInActiveWindow?.let { if (out.none { r -> r == it }) out.add(it) }
        return out
    }

    /** null = can't tell, true = on, false = off */
    private fun stateOf(n: AccessibilityNodeInfo): Boolean? {
        var cur: AccessibilityNodeInfo? = n
        var hops = 0
        while (cur != null && hops < 3) {
            if (cur.isCheckable) return cur.isChecked
            val sd = if (Build.VERSION.SDK_INT >= 30) cur.stateDescription?.toString()?.lowercase() else null
            val l = (label(cur) + " " + (sd ?: "")).lowercase()
            if (Regex("\\b(on|enabled|चालू|ऑन|connected)\\b").containsMatchIn(l)) return true
            if (Regex("\\b(off|disabled|बंद|ऑफ)\\b").containsMatchIn(l)) return false
            cur = cur.parent
            hops++
        }
        return null
    }

    /**
     * Pulls down Quick Settings, finds the tile (e.g. "Hotspot"), checks if it is on/off and taps it if needed.
     * If the tile isn't there, opens the setting's page and flips its switch instead.
     */
    fun toggleSetting(keywords: List<String>, wantOn: Boolean?, settingsAction: String, done: (Boolean) -> Unit) {
        val keys = keywords.map { it.lowercase() }
        fun matches(n: AccessibilityNodeInfo) = n.isVisibleToUser && keys.any { label(n).contains(it) }

        handler.postDelayed({ performGlobalAction(GLOBAL_ACTION_QUICK_SETTINGS) }, 700)
        var tries = 0
        val tryShade = object : Runnable {
            override fun run() {
                tries++
                val tile = allRoots().asSequence().mapNotNull { r -> findNode(r) { matches(it) } }.firstOrNull()
                if (tile != null) {
                    val now = stateOf(tile)
                    if (wantOn == null || now == null || now != wantOn) clickNode(tile)
                    handler.postDelayed({ performGlobalAction(GLOBAL_ACTION_BACK) }, 900)
                    handler.postDelayed({ performGlobalAction(GLOBAL_ACTION_BACK) }, 1300)
                    done(true)
                    return
                }
                if (tries < 6) {
                    handler.postDelayed(this, 700)
                    return
                }
                // Not in the shade -> open the setting page and flip its switch
                performGlobalAction(GLOBAL_ACTION_BACK)
                try {
                    startActivity(Intent(settingsAction).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
                } catch (e: Exception) {
                    done(false)
                    return
                }
                retry(times = 8, every = 900, first = 1500) {
                    val root = rootInActiveWindow ?: return@retry false
                    val sw = findNode(root) { n ->
                        n.isCheckable && n.isVisibleToUser &&
                            (keys.any { k -> label(n).contains(k) || (n.parent?.let { p -> label(p).contains(k) } == true) } ||
                                n.className?.toString()?.contains("Switch") == true)
                    } ?: return@retry false
                    if (wantOn == null || sw.isChecked != wantOn) clickNode(sw)
                    done(true)
                    true
                }
            }
        }
        handler.postDelayed(tryShade, 1600)
    }

    // ---------------- System actions ----------------
    fun takeScreenshot(delayMs: Long) = global(GLOBAL_ACTION_TAKE_SCREENSHOT, delayMs)

    fun global(action: Int, delayMs: Long) {
        handler.postDelayed({ performGlobalAction(action) }, delayMs)
    }

    /** Screen ko upar/neeche scroll karta hai */
    fun scroll(down: Boolean, delayMs: Long) {
        handler.postDelayed({
            val dm = resources.displayMetrics
            val x = dm.widthPixels / 2f
            val h = dm.heightPixels.toFloat()
            val path = Path()
            if (down) {
                path.moveTo(x, h * 0.72f)
                path.lineTo(x, h * 0.28f)
            } else {
                path.moveTo(x, h * 0.28f)
                path.lineTo(x, h * 0.72f)
            }
            val gesture = GestureDescription.Builder()
                .addStroke(GestureDescription.StrokeDescription(path, 0, 320))
                .build()
            dispatchGesture(gesture, null, null)
        }, delayMs)
    }

    companion object {
        @Volatile
        var instance: AssistantService? = null
            private set
    }
}
EOF_MERA
mkdir -p "$(dirname 'app/src/main/java/com/meraassistant/BirdView.kt')"
cat > 'app/src/main/java/com/meraassistant/BirdView.kt' <<'EOF_MERA'
package com.meraassistant

import android.animation.ValueAnimator
import android.content.Context
import android.graphics.Canvas
import android.graphics.LinearGradient
import android.graphics.Paint
import android.graphics.Path
import android.graphics.RadialGradient
import android.graphics.RectF
import android.graphics.Shader
import android.os.SystemClock
import android.util.AttributeSet
import android.view.View
import android.view.animation.LinearInterpolator
import kotlin.math.abs
import kotlin.math.min
import kotlin.math.sin

/**
 * 🐦 Chinu's mascot: a realistic green parakeet (hara totta) on a branch.
 * Idle: gently bobs and blinks · Listening: flaps wings with your voice
 * Thinking: looks around with "..." · Speaking: beak moves while talking
 */
class BirdView @JvmOverloads constructor(
    context: Context,
    attrs: AttributeSet? = null
) : View(context, attrs) {

    enum class State { IDLE, LISTENING, THINKING, SPEAKING }

    var state: State = State.IDLE
        set(value) {
            field = value
            invalidate()
        }

    private var level = 0f
    private var targetLevel = 0f

    private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
    private val path = Path()
    private val rect = RectF()

    private val green = 0xFF34C759.toInt()

    // realistic rose-ringed parakeet palette
    private val headHi = 0xFF7EDB5A.toInt()
    private val headLo = 0xFF3FAE3A.toInt()
    private val bodyHi = 0xFF6CCB4E.toInt()
    private val bodyLo = 0xFF2E8B37.toInt()
    private val bellyHi = 0xFFC7EC86.toInt()
    private val bellyLo = 0xFF8FCB5A.toInt()
    private val wingHi = 0xFF3FA845.toInt()
    private val wingLo = 0xFF1F6E33.toInt()
    private val flight = 0xFF1C5C4A.toInt()
    private val flightTip = 0xFF2E6F86.toInt()
    private val tailHi = 0xFF4FB866.toInt()
    private val tailLo = 0xFF3C7F96.toInt()
    private val beakHi = 0xFFE8383A.toInt()
    private val beakLo = 0xFFA51C22.toInt()
    private val beakDark = 0xFF5E0E12.toInt()
    private val barkHi = 0xFF8A6A4E.toInt()
    private val barkLo = 0xFF4E3826.toInt()
    private val feetC = 0xFF9A8F8A.toInt()

    private val animator = ValueAnimator.ofFloat(0f, 1f).apply {
        duration = 1000L
        repeatCount = ValueAnimator.INFINITE
        interpolator = LinearInterpolator()
        addUpdateListener {
            level += (targetLevel - level) * 0.25f
            if (state != State.LISTENING) targetLevel *= 0.9f
            invalidate()
        }
    }

    /** Pass SpeechRecognizer's onRmsChanged here */
    fun setLevel(rmsDb: Float) {
        targetLevel = ((rmsDb + 2f) / 12f).coerceIn(0f, 1f)
    }

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        animator.start()
    }

    override fun onDetachedFromWindow() {
        animator.cancel()
        super.onDetachedFromWindow()
    }

    private fun alpha(c: Int, a: Int) = (c and 0x00FFFFFF) or (a.coerceIn(0, 255) shl 24)

    private fun lg(x0: Float, y0: Float, x1: Float, y1: Float, a: Int, b: Int) =
        LinearGradient(x0, y0, x1, y1, a, b, Shader.TileMode.CLAMP)

    private fun rg(x: Float, y: Float, rad: Float, a: Int, b: Int) =
        RadialGradient(x, y, rad, a, b, Shader.TileMode.CLAMP)

    private fun fill(c: Int) {
        paint.shader = null
        paint.style = Paint.Style.FILL
        paint.color = c
    }

    private fun stroke(c: Int, w: Float) {
        paint.shader = null
        paint.style = Paint.Style.STROKE
        paint.strokeCap = Paint.Cap.ROUND
        paint.strokeJoin = Paint.Join.ROUND
        paint.strokeWidth = w
        paint.color = c
    }

    /**
     * Drawn in a 100 x 100 box: a green parakeet (hara totta) perched on a branch,
     * facing right, long tail hanging down to the left.
     */
    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        if (width == 0 || height == 0) return
        val t = SystemClock.uptimeMillis() / 1000f
        val s = min(width, height).toFloat()

        canvas.save()
        canvas.translate((width - s) / 2f, (height - s) / 2f)
        canvas.scale(s / 100f, s / 100f)

        // soft rings while listening / speaking
        if (state == State.LISTENING || state == State.SPEAKING) {
            for (k in 0 until 2) {
                val pr = (t * 0.7f + k * 0.5f) % 1f
                stroke(alpha(green, ((1f - pr) * 90).toInt()), 1.6f)
                canvas.drawCircle(52f, 50f, 40f + pr * 9f + level * 5f, paint)
            }
        }

        // ---------- branch ----------
        path.reset()
        path.moveTo(2f, 84f)
        path.cubicTo(30f, 79f, 60f, 80f, 98f, 72f)
        path.lineTo(98f, 77f)
        path.cubicTo(60f, 86f, 30f, 85f, 2f, 90f)
        path.close()
        paint.style = Paint.Style.FILL
        paint.shader = lg(0f, 76f, 0f, 90f, barkHi, barkLo)
        canvas.drawPath(path, paint)
        stroke(0x44000000, 0.5f)
        canvas.drawLine(20f, 85f, 34f, 83.4f, paint)
        canvas.drawLine(66f, 80.5f, 80f, 77.6f, paint)
        // a small leaf on the branch
        path.reset()
        path.moveTo(84f, 75f)
        path.quadTo(90f, 64f, 97f, 62f)
        path.quadTo(94f, 71f, 84f, 75f)
        paint.style = Paint.Style.FILL
        paint.shader = lg(84f, 75f, 97f, 62f, 0xFF5E9E3A.toInt(), 0xFF2F6B24.toInt())
        canvas.drawPath(path, paint)

        // ---------- bird (bobs a little) ----------
        val bob = when (state) {
            State.IDLE -> sin(t * 2f) * 0.8f
            State.LISTENING -> -abs(sin(t * 5f)) * (0.6f + level * 3f)
            State.THINKING -> sin(t * 3f) * 0.6f
            State.SPEAKING -> sin(t * 7f) * 0.6f
        }
        canvas.save()
        canvas.translate(0f, bob)

        // tail: two long central feathers + side feathers
        val sway = sin(t * 1.3f) * 1.5f
        canvas.save()
        canvas.rotate(sway, 40f, 66f)
        for ((dx, len, c) in listOf(Triple(-3.5f, 0.82f, tailLo), Triple(3f, 0.86f, tailLo), Triple(0f, 1f, tailHi))) {
            path.reset()
            path.moveTo(37f + dx, 62f)
            path.cubicTo(30f + dx, 74f, 24f + dx, 86f, 40f - 26f * len + dx, 66f + 32f * len)
            path.cubicTo(28f + dx, 86f, 36f + dx, 74f, 44f + dx, 64f)
            path.close()
            paint.style = Paint.Style.FILL
            paint.shader = lg(40f, 62f, 14f, 98f, c, tailLo)
            canvas.drawPath(path, paint)
        }
        stroke(0x33000000, 0.35f)
        canvas.drawLine(40f, 64f, 15.5f, 97f, paint)
        canvas.restore()

        // feet gripping the branch
        stroke(feetC, 1.6f)
        for (fx in listOf(47f, 55f)) {
            val fy = 80.5f - (fx - 47f) * 0.18f - bob
            canvas.drawLine(fx, 72f, fx + 0.5f, fy - 0.5f, paint)
            path.reset()
            path.moveTo(fx - 2.6f, fy + 1.2f)
            path.quadTo(fx, fy - 1.6f, fx + 3f, fy + 1f)
            canvas.drawPath(path, paint)
        }

        // body: upright teardrop
        path.reset()
        path.moveTo(56f, 30f)
        path.cubicTo(70f, 34f, 70f, 58f, 60f, 70f)
        path.cubicTo(54f, 76f, 44f, 76f, 39f, 68f)
        path.cubicTo(34f, 58f, 40f, 38f, 56f, 30f)
        path.close()
        paint.style = Paint.Style.FILL
        paint.shader = rg(62f, 42f, 36f, bodyHi, bodyLo)
        canvas.drawPath(path, paint)

        // chest / belly: lighter yellow-green
        path.reset()
        path.moveTo(62f, 38f)
        path.cubicTo(70f, 46f, 66f, 64f, 58f, 72f)
        path.cubicTo(55f, 74f, 52f, 73f, 52f, 70f)
        path.cubicTo(58f, 60f, 60f, 48f, 62f, 38f)
        path.close()
        paint.shader = lg(66f, 40f, 54f, 72f, bellyHi, bellyLo)
        canvas.drawPath(path, paint)
        // soft feather scallops on the chest
        stroke(0x2A1F5A1F, 0.45f)
        for (row in 0 until 5) {
            val y = 46f + row * 5f
            val x0 = 63.5f - row * 1.2f
            for (k in 0 until 2) {
                rect.set(x0 - 3f - k * 3.4f, y - 1.6f, x0 - k * 3.4f, y + 1.6f)
                canvas.drawArc(rect, 20f, 140f, false, paint)
            }
        }

        // wing (folded along the side, lifts when listening)
        val flap = when (state) {
            State.LISTENING -> -abs(sin(t * 12f)) * (4f + level * 26f)
            State.SPEAKING -> sin(t * 8f) * 3f
            State.THINKING -> -2f + sin(t * 2f) * 1.5f
            State.IDLE -> sin(t * 1.5f) * 1.2f
        }
        canvas.save()
        canvas.rotate(flap, 55f, 40f)
        path.reset()
        path.moveTo(57f, 37f)
        path.cubicTo(62f, 46f, 56f, 62f, 44f, 76f)
        path.cubicTo(41f, 80f, 37f, 80f, 38f, 74f)
        path.cubicTo(40f, 60f, 44f, 44f, 57f, 37f)
        path.close()
        paint.style = Paint.Style.FILL
        paint.shader = lg(56f, 38f, 40f, 78f, wingHi, wingLo)
        canvas.drawPath(path, paint)
        // covert feather rows
        stroke(0x33103A1A, 0.5f)
        for (i in 0 until 4) {
            val y = 45f + i * 5f
            path.reset()
            path.moveTo(56f - i * 1.6f, y)
            path.quadTo(50f - i * 1.6f, y + 3f, 45f - i * 1.4f, y + 1.5f)
            canvas.drawPath(path, paint)
        }
        // long flight feathers (dark teal tips)
        for (i in 0 until 4) {
            path.reset()
            val ox = 49f - i * 2.2f
            val oy = 62f + i * 1.5f
            path.moveTo(ox + 3f, oy - 4f)
            path.quadTo(ox - 2f, oy + 8f, ox - 7f + i, oy + 15f - i * 1.2f)
            path.quadTo(ox + 1f, oy + 6f, ox + 5.5f, oy - 2f)
            path.close()
            paint.style = Paint.Style.FILL
            paint.shader = lg(ox + 3f, oy - 4f, ox - 6f, oy + 14f, flight, flightTip)
            canvas.drawPath(path, paint)
        }
        canvas.restore()

        // ---------- head (tilts while thinking / listening) ----------
        val tilt = when (state) {
            State.THINKING -> sin(t * 1.6f) * 9f
            State.LISTENING -> -6f
            else -> sin(t * 0.9f) * 2f
        }
        canvas.save()
        canvas.rotate(tilt, 56f, 34f)

        paint.style = Paint.Style.FILL
        paint.shader = rg(60f, 20f, 16f, headHi, headLo)
        canvas.drawCircle(59f, 25f, 12.5f, paint)
        // faint bluish sheen on the back of the head
        paint.shader = rg(54f, 22f, 6f, 0x4460A8C8, 0x0060A8C8)
        canvas.drawCircle(54f, 22f, 6f, paint)
        // cheek feathers
        stroke(0x221F5A1F, 0.45f)
        rect.set(58f, 26f, 66f, 33f)
        canvas.drawArc(rect, 20f, 120f, false, paint)

        // beak: hooked red upper mandible + dark lower one (opens while speaking)
        val open = when (state) {
            State.SPEAKING -> abs(sin(t * 11f)) * 16f
            State.LISTENING -> 4f
            else -> 0f
        }
        canvas.save()
        canvas.rotate(open, 69f, 29f)
        path.reset()
        path.moveTo(69f, 29.5f)
        path.quadTo(73f, 31.5f, 73.5f, 34.5f)
        path.quadTo(70.5f, 34.5f, 68f, 31.5f)
        path.close()
        fill(beakDark)
        canvas.drawPath(path, paint)
        canvas.restore()
        path.reset()
        path.moveTo(68f, 21.5f)
        path.cubicTo(74f, 20.5f, 79.5f, 25f, 78f, 33.5f)      // big curved hook
        path.quadTo(76.5f, 36f, 75.2f, 33f)
        path.cubicTo(74.5f, 30f, 72f, 29f, 68.5f, 30f)
        path.close()
        paint.style = Paint.Style.FILL
        paint.shader = lg(70f, 21f, 77f, 35f, beakHi, beakLo)
        canvas.drawPath(path, paint)
        // highlight on the beak
        stroke(0x66FFFFFF, 0.6f)
        path.reset()
        path.moveTo(70f, 23f)
        path.quadTo(74f, 23f, 76f, 27f)
        canvas.drawPath(path, paint)

        // eye: pale ring, cream iris, black pupil, sparkle; blinks
        val ex = 62.5f
        val ey = 22f
        val blink = if ((t % 3.7f) < 0.13f) 0.1f else 1f
        val look = if (state == State.THINKING) sin(t * 2.5f) * 0.6f else 0.3f
        fill(0xFFE9F3D6.toInt())
        rect.set(ex - 3.3f, ey - 3.3f * blink, ex + 3.3f, ey + 3.3f * blink)
        canvas.drawOval(rect, paint)
        fill(0xFFF3E7B8.toInt())
        rect.set(ex - 2.3f + look, ey - 2.3f * blink, ex + 2.3f + look, ey + 2.3f * blink)
        canvas.drawOval(rect, paint)
        fill(0xFF111111.toInt())
        rect.set(ex - 1.4f + look, ey - 1.4f * blink, ex + 1.4f + look, ey + 1.4f * blink)
        canvas.drawOval(rect, paint)
        if (blink > 0.5f) {
            fill(0xEEFFFFFF.toInt())
            canvas.drawCircle(ex + look + 0.6f, ey - 0.7f, 0.55f, paint)
        } else {
            stroke(headLo, 0.8f)
            canvas.drawLine(ex - 3.3f, ey, ex + 3.3f, ey, paint)
        }
        canvas.restore()      // head
        canvas.restore()      // bob

        // thinking dots
        if (state == State.THINKING) {
            for (i in 0 until 3) {
                val a = ((sin(t * 6f - i * 0.9f) + 1f) / 2f)
                fill(alpha(0xFF8E8E93.toInt(), (80 + a * 175).toInt()))
                canvas.drawCircle(70f + i * 5f, 8f - a * 1.2f, 1.6f, paint)
            }
        }
        paint.shader = null
        canvas.restore()
    }
}
EOF_MERA
mkdir -p "$(dirname 'app/src/main/java/com/meraassistant/Birthday.kt')"
cat > 'app/src/main/java/com/meraassistant/Birthday.kt' <<'EOF_MERA'
package com.meraassistant

import android.Manifest
import android.app.AlarmManager
import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import java.util.Calendar

/**
 * 🎂 Birthday surprise mode:
 * birthday से 2 दिन पहले, 1 दिन पहले, ठीक रात 12 बजे और सुबह 9 बजे notification।
 */
object Birthday {

    private const val CHANNEL = "birthday"

    private val wishesHinglish = listOf(
        "हैप्पी बर्थडे %1\$s! 🎂 भगवान करे आपकी हर ख़्वाहिश पूरी हो, और आपकी मुस्कान हमेशा ऐसे ही चमकती रहे 💚",
        "जन्मदिन मुबारक हो %1\$s! 🎉 आप %2\$s की दुनिया की सबसे ख़ास इंसान हो ✨",
        "हैप्पी बर्थडे %1\$s! 🥳 आज केक भी आपका, दिन भी आपका, और %2\$s का दिल भी आपका 💚",
        "मेनी मेनी हैप्पी रिटर्न्स ऑफ़ द डे, %1\$s! 🎂 ये साल आपके लिए ढेर सारी ख़ुशियाँ और प्यार लाए 🌸",
        "हैप्पी बर्थडे मेरी प्यारी %1\$s! 🎈 %2\$s ने मुझसे कहा है कि आज आपको दुनिया की सबसे ख़ुश लड़की बनाना है 😊💚"
    )
    private val wishesEn = listOf(
        "Happy Birthday %1\$s! 🎂 May all your wishes come true and your smile keep shining forever 💖",
        "Happy Birthday %1\$s! 🎉 You are the most special person in %2\$s's world ✨",
        "Happy Birthday %1\$s! 🥳 Today the cake is yours, the day is yours, and %2\$s's heart is yours too 💖",
        "Many happy returns of the day, %1\$s! 🎂 May this year bring you endless happiness 🌸"
    )

    fun randomWish(p: Profile.Data, hinglish: Boolean): String =
        String.format((if (hinglish) wishesHinglish else wishesEn).random(), p.name, p.partner)

    fun createChannel(ctx: Context) {
        val nm = ctx.getSystemService(NotificationManager::class.java)
        val ch = NotificationChannel(CHANNEL, "Birthday 🎂", NotificationManager.IMPORTANCE_HIGH)
        ch.description = "Birthday reminders and wishes"
        nm.createNotificationChannel(ch)
    }

    /** सारे birthday notifications सेट करता है (जो समय निकल चुका, उन्हें छोड़कर) */
    fun schedule(ctx: Context) {
        createChannel(ctx)
        val p = Profile.load(ctx)
        val bday = Profile.nextDate(p.birthday) ?: return
        val am = ctx.getSystemService(AlarmManager::class.java)
        // (id, कितने दिन पहले, कितने बजे)
        val plan = listOf(Triple(1, -2, 9), Triple(2, -1, 9), Triple(3, 0, 0), Triple(4, 0, 9))
        for ((id, offset, hour) in plan) {
            val t = (bday.clone() as Calendar).apply {
                add(Calendar.DAY_OF_YEAR, offset)
                set(Calendar.HOUR_OF_DAY, hour)
            }
            val pi = PendingIntent.getBroadcast(
                ctx, id,
                Intent(ctx, BirthdayReceiver::class.java).putExtra("kind", id),
                PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
            )
            if (t.timeInMillis <= System.currentTimeMillis()) {
                am.cancel(pi)
                continue
            }
            try {
                val exactOk = Build.VERSION.SDK_INT < Build.VERSION_CODES.S || am.canScheduleExactAlarms()
                if (exactOk) am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, t.timeInMillis, pi)
                else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, t.timeInMillis, pi)
            } catch (e: SecurityException) {
                am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, t.timeInMillis, pi)
            }
        }
    }

    /** Phone restart के बाद "Hello Chinu" फिर चालू करने की याद */
    fun remindWake(ctx: Context) {
        val on = ctx.getSharedPreferences("settings", Context.MODE_PRIVATE).getBoolean("wake", true)
        if (!on) return
        if (Build.VERSION.SDK_INT >= 33 &&
            ctx.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
        ) return
        createChannel(ctx)
        val open = PendingIntent.getActivity(
            ctx, 20, Intent(ctx, MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        val n = Notification.Builder(ctx, CHANNEL)
            .setSmallIcon(R.drawable.ic_mic)
            .setContentTitle("🎙️ Wake up Chinu")
            .setContentText("Your phone restarted. Tap once so \"Hey Chinu\" works again 💖")
            .setContentIntent(open)
            .setAutoCancel(true)
            .build()
        ctx.getSystemService(NotificationManager::class.java).notify(99, n)
    }

    fun notify(ctx: Context, kind: Int) {
        if (Build.VERSION.SDK_INT >= 33 &&
            ctx.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
        ) return
        createChannel(ctx)
        val p = Profile.load(ctx)
        val n = p.name
        Speaker.load(ctx)
        val (title, text) = if (Speaker.owner == true) when (kind) {
            1 -> "🎂 $n's birthday in 2 days!" to "Time to plan something special for her, ${p.partner} 💖"
            2 -> "🎂 Tomorrow is $n's birthday!" to "Be ready to wish her at midnight 🌙"
            3 -> "🎉 It's $n's birthday! 🎂" to "Midnight! Be the first to wish her, ${p.partner} 💖"
            else -> "🎂 Today is $n's birthday!" to "Call her and make her day special 💖"
        } else when (kind) {
            1 -> "🎂 Birthday soon, $n!" to "Just 2 days to go! ${p.partner} and Chinu are super excited 💖"
            2 -> "🎂 Tomorrow is your birthday, $n!" to "One more night... tomorrow is all yours ✨"
            3 -> "🎉 Happy Birthday $n! 🎂" to "It's midnight! Lots of love from ${p.partner} 💖 Open Chinu, a surprise is waiting!"
            else -> "🎂 Happy Birthday $n! 💖" to randomWish(p, false)
        }
        val surprise = kind >= 3 && Bday.isToday() && Speaker.owner != true
        val open = PendingIntent.getActivity(
            ctx, 10 + kind,
            Intent(ctx, if (surprise) BdayActivity::class.java else MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        if (kind == 3 && Bday.isToday() && Speaker.owner == true)
            Voice.say(ctx, "बारह बज गए! आज कोमल का बर्थडे है। सबसे पहले विश कर दो!")
        val notification = Notification.Builder(ctx, CHANNEL)
            .setSmallIcon(R.drawable.ic_mic)
            .setContentTitle(title)
            .setContentText(text)
            .setStyle(Notification.BigTextStyle().bigText(text))
            .setContentIntent(open)
            .setAutoCancel(true)
            .apply { if (surprise && kind == 3) setFullScreenIntent(open, true).setCategory(Notification.CATEGORY_ALARM) }
            .build()
        ctx.getSystemService(NotificationManager::class.java).notify(100 + kind, notification)
        if (surprise && kind == 3) try {
            ctx.startActivity(Intent(ctx, BdayActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
        } catch (e: Exception) {
        }
    }
}

/** Alarm आने पर notification दिखाता है; phone restart होने पर फिर से schedule करता है */
class BirthdayReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        when (intent.action) {
            Intent.ACTION_BOOT_COMPLETED, Intent.ACTION_MY_PACKAGE_REPLACED -> {
                Birthday.schedule(context)
                Birthday.remindWake(context)
            }
            else -> Birthday.notify(context, intent.getIntExtra("kind", 4))
        }
    }
}
