        CoupleLink.send(ctx, "note", JSONObject().put("text", "🍬 " + Ui.t(ctx, "Today you are my $n", "Aaj se aap mere $n ho"))) { ok ->
            if (ok) toast(ctx, "Sent “$n” 🍬", "“$n” bhej diya 🍬") else sent(ctx, false)
        }
