  mkdir -p bday && unzip -o -j -q bday.zip -d bday || true
fi
if [ -d bday ]; then
  mkdir -p app/src/main/assets/bday
  find bday -maxdepth 1 -type f \( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' -o -iname '*.webp' -o -iname '*.mp4' -o -iname '*.3gp' -o -iname '*.webm' -o -iname '*.mov' -o -iname '*.mp3' -o -iname '*.m4a' -o -iname '*.aac' -o -iname '*.ogg' -o -iname '*.wav' \) -exec cp {} app/src/main/assets/bday/ \;
  echo "bday assets: $(ls app/src/main/assets/bday | wc -l) files"
fi
